INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak63-rtg-2025', 'p-novak-1963', '2025-01-09', 'imaging', 'RTG kyčelních kloubů — popis', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Radiodiagnostické pracoviště
RTG kyčelních kloubů — popis
Pacient:
Michal Novák
Datum narození:
19.7.1963
Datum vyšetření:
9.1.2025
Popsal:
MUDr. Eva Puchmertlová
Provedené vyšetření
Technika: RTG pánve předozadně ve stoje, doplněn axiální snímek levého kyčelního kloubu.
Indikace: bolesti levé kyčle s propagací do třísla a stehna, klaudikační interval pod 300 m, konzervativní terapie bez
efektu.
Popis
Vlevo je kloubní štěrbina zúžená na 1 mm v horní zátěžové zóně, se subchondrální sklerózou stropu acetabula i hlavice. Na
okraji hlavice a při okraji acetabula jsou patrné osteofyty, největší laterálně, velikosti 6 mm. V hlavici je cystické
projasnění průměru 8 mm. Tvar hlavice je oploštělý, centrace zachována.
Vpravo je kloubní štěrbina zachovalá, výšky 3,5 mm, s naznačenou subchondrální sklerózou stropu acetabula, bez
osteofytů a bez cyst.
Kostní struktura přiměřená věku, bez ložiskových změn. Symfýza a sakroiliakální skloubení bez patologie. Měkké tkáně bez
kalcifikací.
Závěr
Pokročilá koxartróza vlevo (odpovídá stupni III–IV), počínající degenerativní změny vpravo. Nález na levé straně koreluje s
klinickými obtížemi a je indikací k totální endoprotéze.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. radiodiagnosticke pracoviste rtg kycelnich kloubu — popis pacient: michal novak datum narozeni: 19.7.1963 datum vysetreni: 9.1.2025 popsal: mudr. eva puchmertlova provedene vysetreni technika: rtg panve predozadne ve stoje, doplnen axialni snimek leveho kycelniho kloubu. indikace: bolesti leve kycle s propagaci do trisla a stehna, klaudikacni interval pod 300 m, konzervativni terapie bez efektu. popis vlevo je kloubni sterbina zuzena na 1 mm v horni zatezove zone, se subchondralni sklerozou stropu acetabula i hlavice. na okraji hlavice a pri okraji acetabula jsou patrne osteofyty, nejvetsi lateralne, velikosti 6 mm. v hlavici je cysticke projasneni prumeru 8 mm. tvar hlavice je oplostely, centrace zachovana. vpravo je kloubni sterbina zachovala, vysky 3,5 mm, s naznacenou subchondralni sklerozou stropu acetabula, bez osteofytu a bez cyst. kostni struktura primerena veku, bez loziskovych zmen. symfyza a sakroiliakalni skloubeni bez patologie. mekke tkane bez kalcifikaci. zaver pokrocila koxartroza vlevo (odpovida stupni iii–iv), pocinajici degenerativni zmeny vpravo. nalez na leve strane koreluje s klinickymi obtizemi a je indikaci k totalni endoproteze. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak63-operace-2025', 'p-novak-1963', '2025-02-03', 'op_report', 'Operační protokol — TEP levého kyčelního kloubu', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Ortopedické oddělení — operační sál
Operační protokol — TEP levého kyčelního kloubu
Pacient:
Michal Novák
Datum narození:
19.7.1963
Datum výkonu:
3.2.2025
Operatér:
MUDr. Kamil Brandejs
Základní údaje
Diagnóza: primární koxartróza vlevo, pokročilý stupeň.
Výkon: totální endoprotéza levého kyčelního kloubu, necementovaná.
Anestezie: spinální, sedace.
Asistence: MUDr. Vít Pospíchal
Poloha: na pravém boku, standardní fixace pánve.
Antibiotická profylaxe: podána 30 minut před incizí, jedna dávka.
Popis výkonu
Anterolaterální přístup v délce 12 cm. Protětí podkoží a fascie, šetrné odtažení gluteální muskulatury. Kloubní pouzdro
T-tvarem protnuto, hlavice luxována. Kloubní chrupavka acetabula prakticky vymizelá, na hlavici mnohočetné osteofyty
odpovídající předoperačnímu snímku.
Osteotomie krčku podle předoperačního plánování, 1 cm nad malým trochanterem. Postupné frézování acetabula do
velikosti 52 mm, zachována subchondrální kost. Zavedena necementovaná jamka 52 mm v inklinaci 42° a anteverzi 15°,
primární stabilita dobrá, bez nutnosti doplňkové fixace šroubem. Vložka polyetylenová.
Femorální kanál postupně rozšířen rašplemi do velikosti 5. Zkušební repozice s krčkem střední délky — rozsah pohybu
volný, bez impingementu, délka končetin vyrovnaná, stabilita v addukci i zevní rotaci dobrá. Zaveden definitivní
necementovaný dřík velikosti 5, nasazena keramická hlavice 32 mm, repozice.
Výplach, kontrola hemostázy, Redonův drén do rány. Sutura pouzdra, fascie a podkoží po vrstvách, intradermální sutura
kůže, krytí.
Průběh a bezprostřední pooperační období
Doba výkonu: 68 minut.
Krevní ztráta: cca 350 ml, bez podání krevního převodu.
Komplikace: v průběhu výkonu žádné.
Pooperační plán: nízkomolekulární heparin 35 dní, drén ex 1. pooperační den, vertikalizace 1. pooperační den, chůze o
dvou francouzských holích s částečnou zátěží operované končetiny, ambulantní rehabilitace od 3.
týdne, kontrola za 6 týdnů.
Kontrolní laboratoř 3. pooperační den
Odběr 6. 2. 2025: B_Hemoglobin 104 g/l, B_Hematokrit 0,311, B_Leukocyty 11,80 10^9/l, B_Trombocyty 402 10^9/l,
S_CRP 78,4 mg/l. Pokles hemoglobinu i vzestup zánětlivých parametrů odpovídají rozsahu výkonu a třetímu pooperačnímu
dni, rána je klidná, bez sekrece. Bez indikace k transfuzi, doporučena perorální substituce železa a kontrolní odběr při
ambulantní kontrole.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. ortopedicke oddeleni — operacni sal operacni protokol — tep leveho kycelniho kloubu pacient: michal novak datum narozeni: 19.7.1963 datum vykonu: 3.2.2025 operater: mudr. kamil brandejs zakladni udaje diagnoza: primarni koxartroza vlevo, pokrocily stupen. vykon: totalni endoproteza leveho kycelniho kloubu, necementovana. anestezie: spinalni, sedace. asistence: mudr. vit pospichal poloha: na pravem boku, standardni fixace panve. antibioticka profylaxe: podana 30 minut pred incizi, jedna davka. popis vykonu anterolateralni pristup v delce 12 cm. proteti podkozi a fascie, setrne odtazeni glutealni muskulatury. kloubni pouzdro t-tvarem protnuto, hlavice luxovana. kloubni chrupavka acetabula prakticky vymizela, na hlavici mnohocetne osteofyty odpovidajici predoperacnimu snimku. osteotomie krcku podle predoperacniho planovani, 1 cm nad malym trochanterem. postupne frezovani acetabula do velikosti 52 mm, zachovana subchondralni kost. zavedena necementovana jamka 52 mm v inklinaci 42° a anteverzi 15°, primarni stabilita dobra, bez nutnosti doplnkove fixace sroubem. vlozka polyetylenova. femoralni kanal postupne rozsiren rasplemi do velikosti 5. zkusebni repozice s krckem stredni delky — rozsah pohybu volny, bez impingementu, delka koncetin vyrovnana, stabilita v addukci i zevni rotaci dobra. zaveden definitivni necementovany drik velikosti 5, nasazena keramicka hlavice 32 mm, repozice. vyplach, kontrola hemostazy, redonuv dren do rany. sutura pouzdra, fascie a podkozi po vrstvach, intradermalni sutura kuze, kryti. prubeh a bezprostredni pooperacni obdobi doba vykonu: 68 minut. krevni ztrata: cca 350 ml, bez podani krevniho prevodu. komplikace: v prubehu vykonu zadne. pooperacni plan: nizkomolekularni heparin 35 dni, dren ex 1. pooperacni den, vertikalizace 1. pooperacni den, chuze o dvou francouzskych holich s castecnou zatezi operovane koncetiny, ambulantni rehabilitace od 3. tydne, kontrola za 6 tydnu. kontrolni laborator 3. pooperacni den odber 6. 2. 2025: b_hemoglobin 104 g/l, b_hematokrit 0,311, b_leukocyty 11,80 10^9/l, b_trombocyty 402 10^9/l, s_crp 78,4 mg/l. pokles hemoglobinu i vzestup zanetlivych parametru odpovidaji rozsahu vykonu a tretimu pooperacnimu dni, rana je klidna, bez sekrece. bez indikace k transfuzi, doporucena peroralni substituce zeleza a kontrolni odber pri ambulantni kontrole. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak63-fyzio-2025a', 'p-novak-1963', '2025-02-17', 'physio_note', 'Záznam z fyzioterapie', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie
Pacient:
Michal Novák
Datum narození:
19.7.1963
Datum terapie:
17.2.2025
Terapeut:
Bc. Lenka Zemanová
Diagnóza: stav po TEP levého kyčelního kloubu 3. 2. 2025, 14. pooperační den.
Návštěva: 1. ze série 10.
Subjektivně
Bolest v okolí jizvy při chůzi, v noci klid. Chůze o dvou francouzských holích zvládá po bytě, schody zatím s dopomocí
manželky. Obává se plné zátěže operované končetiny.
Bolest (VAS): 4/10 při zátěži, 1/10 v klidu.
Objektivně
Jizva klidná, bez sekrece, mírně oteklé okolí. Flexe levé kyčle aktivně 75°, pasivně 85°. Abdukce 20°. Zevní rotace
omezena bolestí. Trendelenburgův příznak vlevo pozitivní. Obvod stehna 15 cm nad patellou vlevo o 2,5 cm menší než
vpravo.
Terapie
Měkké techniky v okolí jizvy, lymfatické techniky na stehno. Izometrická aktivace gluteálních svalů a kvadricepsu, 3 série
po 10 opakováních. Nácvik chůze o dvou holích s částečnou zátěží 30 kg, kontrola na váze. Nácvik chůze do schodů a ze
schodů.
Plán
Domácí cvičební jednotka 2× denně, izometrie a aktivní pohyb do flexe do hranice bolesti. Dodržovat zákaz flexe nad 90°,
addukce přes střední čáru a vnitřní rotace do 6 týdnů od operace. Kontrola za týden.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie pacient: michal novak datum narozeni: 19.7.1963 datum terapie: 17.2.2025 terapeut: bc. lenka zemanova diagnoza: stav po tep leveho kycelniho kloubu 3. 2. 2025, 14. pooperacni den. navsteva: 1. ze serie 10. subjektivne bolest v okoli jizvy pri chuzi, v noci klid. chuze o dvou francouzskych holich zvlada po byte, schody zatim s dopomoci manzelky. obava se plne zateze operovane koncetiny. bolest (vas): 4/10 pri zatezi, 1/10 v klidu. objektivne jizva klidna, bez sekrece, mirne otekle okoli. flexe leve kycle aktivne 75°, pasivne 85°. abdukce 20°. zevni rotace omezena bolesti. trendelenburguv priznak vlevo pozitivni. obvod stehna 15 cm nad patellou vlevo o 2,5 cm mensi nez vpravo. terapie mekke techniky v okoli jizvy, lymfaticke techniky na stehno. izometricka aktivace glutealnich svalu a kvadricepsu, 3 serie po 10 opakovanich. nacvik chuze o dvou holich s castecnou zatezi 30 kg, kontrola na vaze. nacvik chuze do schodu a ze schodu. plan domaci cvicebni jednotka 2× denne, izometrie a aktivni pohyb do flexe do hranice bolesti. dodrzovat zakaz flexe nad 90°, addukce pres stredni caru a vnitrni rotace do 6 tydnu od operace. kontrola za tyden. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak63-fyzio-2025b', 'p-novak-1963', '2025-03-11', 'physio_note', 'Záznam z fyzioterapie', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie
Pacient:
Michal Novák
Datum narození:
19.7.1963
Datum terapie:
11.3.2025
Terapeut:
Bc. Lenka Zemanová
Diagnóza: stav po TEP levého kyčelního kloubu 3. 2. 2025, 5. pooperační týden.
Návštěva: 5. ze série 10.
Subjektivně
Zlepšení proti minulé návštěvě. Chůze o jedné holi venku do 20 minut, bez nutnosti odpočinku. Bolest jen po delší chůzi.
Domácí cvičení provádí pravidelně.
Bolest (VAS): 2/10 po zátěži, 0/10 v klidu.
Objektivně
Jizva zhojena, posunlivá. Otok stehna ustoupil. Flexe levé kyčle aktivně 95°, abdukce 30°. Trendelenburgův příznak vlevo
jen naznačený. Obvod stehna vlevo o 1,5 cm menší než vpravo. Chůze o jedné holi se symetrickým krokem.
Terapie
Posilování abduktorů v odlehčení a proti gravitaci, 3 série po 12 opakováních. Aktivace hlubokého stabilizačního systému.
Nácvik stoje na operované končetině s oporou, výdrž 3× 20 sekund. Rotoped 10 minut bez odporu.
Plán
Odložit druhou hůl v průběhu příštího týdne, chůzi prodlužovat postupně. Rotoped denně 15 minut. Nadále bez flexe nad
90° při sedu na nízké židli. Kontrola za dva týdny.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie pacient: michal novak datum narozeni: 19.7.1963 datum terapie: 11.3.2025 terapeut: bc. lenka zemanova diagnoza: stav po tep leveho kycelniho kloubu 3. 2. 2025, 5. pooperacni tyden. navsteva: 5. ze serie 10. subjektivne zlepseni proti minule navsteve. chuze o jedne holi venku do 20 minut, bez nutnosti odpocinku. bolest jen po delsi chuzi. domaci cviceni provadi pravidelne. bolest (vas): 2/10 po zatezi, 0/10 v klidu. objektivne jizva zhojena, posunliva. otok stehna ustoupil. flexe leve kycle aktivne 95°, abdukce 30°. trendelenburguv priznak vlevo jen naznaceny. obvod stehna vlevo o 1,5 cm mensi nez vpravo. chuze o jedne holi se symetrickym krokem. terapie posilovani abduktoru v odlehceni a proti gravitaci, 3 serie po 12 opakovanich. aktivace hlubokeho stabilizacniho systemu. nacvik stoje na operovane koncetine s oporou, vydrz 3× 20 sekund. rotoped 10 minut bez odporu. plan odlozit druhou hul v prubehu pristiho tydne, chuzi prodluzovat postupne. rotoped denne 15 minut. nadale bez flexe nad 90° pri sedu na nizke zidli. kontrola za dva tydny. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak63-fyzio-2025c', 'p-novak-1963', '2025-04-15', 'physio_note', 'Záznam z fyzioterapie — závěr série', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie — závěr série
Pacient:
Michal Novák
Datum narození:
19.7.1963
Datum terapie:
15.4.2025
Terapeut:
Bc. Lenka Zemanová
Diagnóza: stav po TEP levého kyčelního kloubu 3. 2. 2025, 10. pooperační týden.
Návštěva: 10. ze série 10, závěrečná.
Subjektivně
Bez bolestí při běžných denních činnostech. Chůze bez opory, venku i hodinu. Schody střídavým krokem. Vrátil se k práci
na zahradě, delší práci v předklonu zatím nezkoušel.
Bolest (VAS): 1/10 po delší chůzi, jinak 0/10.
Objektivně
Flexe levé kyčle aktivně 110°, abdukce 40°, zevní rotace volná. Trendelenburgův příznak negativní. Obvod stehna vlevo o
0,5 cm menší než vpravo. Stoj na jedné noze 20 sekund bez opory. Chůze bez antalgického vzorce.
Terapie
Posilování abduktorů a extenzorů s odporovou gumou, senzomotorická cvičení na labilní ploše, korekce stereotypu chůze.
Instruktáž autoterapie.
Plán
Série ukončena, cíle dosaženy. Doporučeno pokračovat v domácím cvičení denně, plavání a rotoped bez omezení, chůze
bez limitu. Doživotně se vyhnout nárazovým sportům a zvedání těžkých břemen v předklonu. Ortopedická kontrola za 6
měsíců.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie — zaver serie pacient: michal novak datum narozeni: 19.7.1963 datum terapie: 15.4.2025 terapeut: bc. lenka zemanova diagnoza: stav po tep leveho kycelniho kloubu 3. 2. 2025, 10. pooperacni tyden. navsteva: 10. ze serie 10, zaverecna. subjektivne bez bolesti pri beznych dennich cinnostech. chuze bez opory, venku i hodinu. schody stridavym krokem. vratil se k praci na zahrade, delsi praci v predklonu zatim nezkousel. bolest (vas): 1/10 po delsi chuzi, jinak 0/10. objektivne flexe leve kycle aktivne 110°, abdukce 40°, zevni rotace volna. trendelenburguv priznak negativni. obvod stehna vlevo o 0,5 cm mensi nez vpravo. stoj na jedne noze 20 sekund bez opory. chuze bez antalgickeho vzorce. terapie posilovani abduktoru a extenzoru s odporovou gumou, senzomotoricka cviceni na labilni plose, korekce stereotypu chuze. instruktaz autoterapie. plan serie ukoncena, cile dosazeny. doporuceno pokracovat v domacim cviceni denne, plavani a rotoped bez omezeni, chuze bez limitu. dozivotne se vyhnout narazovym sportum a zvedani tezkych bremen v predklonu. ortopedicka kontrola za 6 mesicu. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak88-mr-2024', 'p-novak-1988', '2024-09-20', 'imaging', 'MR pravého kolenního kloubu — popis', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Radiodiagnostické pracoviště
MR pravého kolenního kloubu — popis
Pacient:
Michal Novák
Datum narození:
27.2.1988
Datum vyšetření:
20.9.2024
Popsal:
MUDr. Eva Puchmertlová
Provedené vyšetření
Technika: MR pravého kolena 1,5 T, sekvence PD FS v rovině sagitální, koronární a transverzální, T1 sagitálně, bez
podání kontrastní látky.
Indikace: distorze kolena při fotbale 14. 9. 2024, pocit nestability, výpotek.
Popis
Přední zkřížený vaz není ve svém průběhu zobrazen v kontinuitě, v oblasti proximální třetiny je patrné přerušení vláken s
edémem v okolí. Zbylá vlákna jsou horizontalizovaná. Nález odpovídá kompletní ruptuře.
Zadní zkřížený vaz intaktní, s fyziologickým signálem. Vnitřní i zevní postranní vaz bez známek léze.
Mediální meniskus: v zadním rohu horizontální linie zvýšeného signálu dosahující spodní kloubní plochy, odpovídá parciální
lézi. Laterální meniskus bez léze.
Kostní kontuze laterálního femorálního kondylu a dorzolaterální části tibiálního plató — typická lokalizace pro
mechanismus poranění předního zkříženého vazu. Chrupavka bez ložiskového defektu. V kloubu je výpotek středního
rozsahu. Bakerova cysta se nezobrazuje.
Závěr
Kompletní ruptura předního zkříženého vazu (LCA) pravého kolena, parciální léze zadního rohu mediálního menisku, kostní
kontuze laterálního kondylu femuru, výpotek. Nález je indikací k plastice předního zkříženého vazu po odeznění otoku a
obnovení rozsahu pohybu.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. radiodiagnosticke pracoviste mr praveho kolenniho kloubu — popis pacient: michal novak datum narozeni: 27.2.1988 datum vysetreni: 20.9.2024 popsal: mudr. eva puchmertlova provedene vysetreni technika: mr praveho kolena 1,5 t, sekvence pd fs v rovine sagitalni, koronarni a transverzalni, t1 sagitalne, bez podani kontrastni latky. indikace: distorze kolena pri fotbale 14. 9. 2024, pocit nestability, vypotek. popis predni zkrizeny vaz neni ve svem prubehu zobrazen v kontinuite, v oblasti proximalni tretiny je patrne preruseni vlaken s edemem v okoli. zbyla vlakna jsou horizontalizovana. nalez odpovida kompletni rupture. zadni zkrizeny vaz intaktni, s fyziologickym signalem. vnitrni i zevni postranni vaz bez znamek leze. medialni meniskus: v zadnim rohu horizontalni linie zvyseneho signalu dosahujici spodni kloubni plochy, odpovida parcialni lezi. lateralni meniskus bez leze. kostni kontuze lateralniho femoralniho kondylu a dorzolateralni casti tibialniho plato — typicka lokalizace pro mechanismus poraneni predniho zkrizeneho vazu. chrupavka bez loziskoveho defektu. v kloubu je vypotek stredniho rozsahu. bakerova cysta se nezobrazuje. zaver kompletni ruptura predniho zkrizeneho vazu (lca) praveho kolena, parcialni leze zadniho rohu medialniho menisku, kostni kontuze lateralniho kondylu femuru, vypotek. nalez je indikaci k plastice predniho zkrizeneho vazu po odezneni otoku a obnoveni rozsahu pohybu. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak88-operace-2024', 'p-novak-1988', '2024-10-08', 'op_report', 'Operační protokol — artroskopická plastika LCA pravého kolena', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Ortopedické oddělení — operační sál
Operační protokol — artroskopická plastika LCA pravého kolena
Pacient:
Michal Novák
Datum narození:
27.2.1988
Datum výkonu:
8.10.2024
Operatér:
MUDr. Kamil Brandejs
Základní údaje
Diagnóza: kompletní ruptura předního zkříženého vazu pravého kolena, parciální léze mediálního menisku.
Výkon: artroskopická plastika předního zkříženého vazu štěpem ze šlach hamstringů, parciální meniscektomie.
Anestezie: spinální, turniket na stehně 250 mmHg.
Asistence: MUDr. Vít Pospíchal
Popis výkonu
Standardní anterolaterální a anteromediální porty. Diagnostická artroskopie: v kloubu mírný výpotek, synovie klidná.
Přední zkřížený vaz zcela přerušen, pahýl resekován. Zadní zkřížený vaz intaktní. Chrupavka femuru i tibie bez defektu.
Zadní roh mediálního menisku s horizontální lézí nedosahující stabilní zóny — provedena šetrná parciální resekce
nestabilní části, zbylý meniskus stabilní při palpaci háčkem. Laterální meniskus intaktní.
Odběr šlach musculus semitendinosus a gracilis z mediální incize, štěp složen na čtyři pruhy, průměr 8,5 mm, délka 90
mm, armován. Tibiální tunel vrtán pod úhlem 55°, femorální tunel technikou přes anteromediální port, délka 40 mm. Štěp
protažen, femorálně fixován závěsným systémem, tibiálně interferenčním šroubem 9 mm při 20° flexe a plné extenzi bez
impingementu.
Kontrola rozsahu pohybu — plná extenze, flexe 130°, přední zásuvka negativní, Lachmanův test negativní. Výplach, drén
nezaveden, sutura portů a odběrové incize.
Průběh a pooperační plán
Doba výkonu: 82 minut.
Komplikace: žádné.
Pooperační plán: ortéza s limitem 0–90° na 4 týdny, poté volná; chůze o dvou francouzských holích s odlehčením 2
týdny; nízkomolekulární heparin 14 dní; ambulantní rehabilitace od 10. dne; kontrola za 3 týdny.
Doporučení k zátěži: rotoped od 3. týdne, plavání od 6. týdne, běh v přímém směru nejdříve od 4. měsíce, kontaktní
sport nejdříve za 9 měsíců a po funkčním testování.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. ortopedicke oddeleni — operacni sal operacni protokol — artroskopicka plastika lca praveho kolena pacient: michal novak datum narozeni: 27.2.1988 datum vykonu: 8.10.2024 operater: mudr. kamil brandejs zakladni udaje diagnoza: kompletni ruptura predniho zkrizeneho vazu praveho kolena, parcialni leze medialniho menisku. vykon: artroskopicka plastika predniho zkrizeneho vazu stepem ze slach hamstringu, parcialni meniscektomie. anestezie: spinalni, turniket na stehne 250 mmhg. asistence: mudr. vit pospichal popis vykonu standardni anterolateralni a anteromedialni porty. diagnosticka artroskopie: v kloubu mirny vypotek, synovie klidna. predni zkrizeny vaz zcela prerusen, pahyl resekovan. zadni zkrizeny vaz intaktni. chrupavka femuru i tibie bez defektu. zadni roh medialniho menisku s horizontalni lezi nedosahujici stabilni zony — provedena setrna parcialni resekce nestabilni casti, zbyly meniskus stabilni pri palpaci hackem. lateralni meniskus intaktni. odber slach musculus semitendinosus a gracilis z medialni incize, step slozen na ctyri pruhy, prumer 8,5 mm, delka 90 mm, armovan. tibialni tunel vrtan pod uhlem 55°, femoralni tunel technikou pres anteromedialni port, delka 40 mm. step protazen, femoralne fixovan zavesnym systemem, tibialne interferencnim sroubem 9 mm pri 20° flexe a plne extenzi bez impingementu. kontrola rozsahu pohybu — plna extenze, flexe 130°, predni zasuvka negativni, lachmanuv test negativni. vyplach, dren nezaveden, sutura portu a odberove incize. prubeh a pooperacni plan doba vykonu: 82 minut. komplikace: zadne. pooperacni plan: orteza s limitem 0–90° na 4 tydny, pote volna; chuze o dvou francouzskych holich s odlehcenim 2 tydny; nizkomolekularni heparin 14 dni; ambulantni rehabilitace od 10. dne; kontrola za 3 tydny. doporuceni k zatezi: rotoped od 3. tydne, plavani od 6. tydne, beh v primem smeru nejdrive od 4. mesice, kontaktni sport nejdrive za 9 mesicu a po funkcnim testovani. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak88-fyzio-2024a', 'p-novak-1988', '2024-11-05', 'physio_note', 'Záznam z fyzioterapie', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie
Pacient:
Michal Novák
Datum narození:
27.2.1988
Datum terapie:
5.11.2024
Terapeut:
Mgr. Petr Hlaváček
Diagnóza: stav po plastice předního zkříženého vazu (LCA) pravého kolena 8. 10. 2024, 4. pooperační týden.
Návštěva: 4. ze série 12.
Subjektivně
Bolest minimální, spíše pocit napětí v podkolení po cvičení. Ortézu odložil podle instrukcí tento týden. Chůze bez holí po
rovině, mírné kulhání při delší chůzi.
Bolest (VAS): 2/10 po cvičení, 0/10 v klidu.
Objektivně
Otok kolena mírný, obvod přes patellu vpravo o 1 cm větší. Extenze plná, aktivně 0°, flexe 105°. Jizvy klidné. Obvod
stehna 10 cm nad patellou vpravo o 2 cm menší než vlevo. Aktivace kvadricepsu oslabená, patella pohyblivá.
Terapie
Mobilizace patelly, měkké techniky na jizvy a hamstringy. Aktivace kvadricepsu s elektrostimulací, 3 série po 15
opakováních. Uzavřené kinetické řetězce: dřep do 60° s oporou, výpony. Rotoped 12 minut bez odporu.
Plán
Zvyšovat rozsah flexe na 120° do konce měsíce, pokračovat v posilování kvadricepsu, přidat leg press v rozsahu 0–60°.
Bez rotačních pohybů a bez běhu. Kontrola za týden.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie pacient: michal novak datum narozeni: 27.2.1988 datum terapie: 5.11.2024 terapeut: mgr. petr hlavacek diagnoza: stav po plastice predniho zkrizeneho vazu (lca) praveho kolena 8. 10. 2024, 4. pooperacni tyden. navsteva: 4. ze serie 12. subjektivne bolest minimalni, spise pocit napeti v podkoleni po cviceni. ortezu odlozil podle instrukci tento tyden. chuze bez holi po rovine, mirne kulhani pri delsi chuzi. bolest (vas): 2/10 po cviceni, 0/10 v klidu. objektivne otok kolena mirny, obvod pres patellu vpravo o 1 cm vetsi. extenze plna, aktivne 0°, flexe 105°. jizvy klidne. obvod stehna 10 cm nad patellou vpravo o 2 cm mensi nez vlevo. aktivace kvadricepsu oslabena, patella pohybliva. terapie mobilizace patelly, mekke techniky na jizvy a hamstringy. aktivace kvadricepsu s elektrostimulaci, 3 serie po 15 opakovanich. uzavrene kineticke retezce: drep do 60° s oporou, vypony. rotoped 12 minut bez odporu. plan zvysovat rozsah flexe na 120° do konce mesice, pokracovat v posilovani kvadricepsu, pridat leg press v rozsahu 0–60°. bez rotacnich pohybu a bez behu. kontrola za tyden. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-novak88-fyzio-2024b', 'p-novak-1988', '2024-12-16', 'physio_note', 'Záznam z fyzioterapie', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie
Pacient:
Michal Novák
Datum narození:
27.2.1988
Datum terapie:
16.12.2024
Terapeut:
Mgr. Petr Hlaváček
Diagnóza: stav po plastice předního zkříženého vazu (LCA) pravého kolena 8. 10. 2024, 10. pooperační týden.
Návštěva: 10. ze série 12.
Subjektivně
Bez bolestí. Chůze bez omezení, zvládá schody střídavým krokem i sestup. Subjektivně se cítí připraven na běh a ptá se,
kdy může začít.
Bolest (VAS): 1/10 po delším zatížení, jinak 0/10.
Objektivně
Koleno bez otoku, obvody symetrické. Extenze plná, flexe 130°, shodně s druhou stranou. Obvod stehna vpravo o 1,5 cm
menší než vlevo — přetrvává deficit kvadricepsu. Stoj na jedné noze 30 sekund, mírná stranová oscilace. Skok na jedné
noze zatím netestován.
Terapie
Posilování s odporem: leg press, dřepy do 90°, výpady. Senzomotorická cvičení na balanční podložce, nácvik změn směru
v pomalém tempu. Protažení hamstringů a lýtka.
Plán
Běh v přímém směru nejdříve od 4. měsíce po operaci, tedy nejdříve v únoru, a pouze při deficitu síly kvadricepsu pod 15
% proti druhé straně. Pacient poučen, že subjektivní pocit připravenosti předbíhá hojení štěpu. Funkční testování na konci
série.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie pacient: michal novak datum narozeni: 27.2.1988 datum terapie: 16.12.2024 terapeut: mgr. petr hlavacek diagnoza: stav po plastice predniho zkrizeneho vazu (lca) praveho kolena 8. 10. 2024, 10. pooperacni tyden. navsteva: 10. ze serie 12. subjektivne bez bolesti. chuze bez omezeni, zvlada schody stridavym krokem i sestup. subjektivne se citi pripraven na beh a pta se, kdy muze zacit. bolest (vas): 1/10 po delsim zatizeni, jinak 0/10. objektivne koleno bez otoku, obvody symetricke. extenze plna, flexe 130°, shodne s druhou stranou. obvod stehna vpravo o 1,5 cm mensi nez vlevo — pretrvava deficit kvadricepsu. stoj na jedne noze 30 sekund, mirna stranova oscilace. skok na jedne noze zatim netestovan. terapie posilovani s odporem: leg press, drepy do 90°, vypady. senzomotoricka cviceni na balancni podlozce, nacvik zmen smeru v pomalem tempu. protazeni hamstringu a lytka. plan beh v primem smeru nejdrive od 4. mesice po operaci, tedy nejdrive v unoru, a pouze pri deficitu sily kvadricepsu pod 15 % proti druhe strane. pacient poucen, ze subjektivni pocit pripravenosti predbiha hojeni stepu. funkcni testovani na konci serie. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-bezdickova-mr-2024', 'p-bezdickova-1971', '2024-05-06', 'imaging', 'MR bederní páteře — popis', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Radiodiagnostické pracoviště
MR bederní páteře — popis
Pacient:
Jarmila Bezdíčková
Datum narození:
14.5.1971
Datum vyšetření:
6.5.2024
Popsal:
MUDr. Eva Puchmertlová
Provedené vyšetření
Technika: MR bederní páteře 1,5 T, T2 sagitálně a transverzálně, T1 sagitálně, STIR sagitálně, bez kontrastní látky.
Indikace: chronické bolesti bederní páteře trvající 18 měsíců, občasná propagace do levé hýždě, bez neurologického
deficitu.
Popis
Fyziologická lordóza je oploštělá. Obratlová těla mají přiměřenou výšku a signál, bez známek úrazových či ložiskových
změn. Konus medullaris končí na úrovni L1.
L3/4: mírná dehydratace disku, bez protruze, páteřní kanál i foramina volná.
L4/5: snížená výška a signál disku, cirkulární protruze 3 mm, mírná hypertrofie žlutých vazů a facetových kloubů, durální
vak lehce oploštělý, kořeny volné.
L5/S1: snížený signál disku, mediolaterální protruze vlevo velikosti 5 mm, která se dotýká levého kořene S1 v recesu, bez
jeho jasné komprese a bez edému kořene. V krycích ploténkách přilehlých obratlů jsou změny typu Modic I v malém
rozsahu.
Sakroiliakální skloubení bez zánětlivých změn. Paravertebrální měkké tkáně bez patologie.
Závěr
Degenerativní změny bederní páteře, nejvýrazněji L5/S1 s mediolaterální protruzí vlevo v kontaktu s kořenem S1, a L4/5 s
cirkulární protruzí. Nález nevysvětluje úplně rozsah a trvání obtíží; není přítomna komprese kořene ani stenóza kanálu,
které by měnily terapeutický postup. Doporučen konzervativní postup a fyzioterapie.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. radiodiagnosticke pracoviste mr bederni patere — popis pacient: jarmila bezdickova datum narozeni: 14.5.1971 datum vysetreni: 6.5.2024 popsal: mudr. eva puchmertlova provedene vysetreni technika: mr bederni patere 1,5 t, t2 sagitalne a transverzalne, t1 sagitalne, stir sagitalne, bez kontrastni latky. indikace: chronicke bolesti bederni patere trvajici 18 mesicu, obcasna propagace do leve hyzde, bez neurologickeho deficitu. popis fyziologicka lordoza je oplostela. obratlova tela maji primerenou vysku a signal, bez znamek urazovych ci loziskovych zmen. konus medullaris konci na urovni l1. l3/4: mirna dehydratace disku, bez protruze, paterni kanal i foramina volna. l4/5: snizena vyska a signal disku, cirkularni protruze 3 mm, mirna hypertrofie zlutych vazu a facetovych kloubu, duralni vak lehce oplostely, koreny volne. l5/s1: snizeny signal disku, mediolateralni protruze vlevo velikosti 5 mm, ktera se dotyka leveho korene s1 v recesu, bez jeho jasne komprese a bez edemu korene. v krycich plotenkach prilehlych obratlu jsou zmeny typu modic i v malem rozsahu. sakroiliakalni skloubeni bez zanetlivych zmen. paravertebralni mekke tkane bez patologie. zaver degenerativni zmeny bederni patere, nejvyrazneji l5/s1 s mediolateralni protruzi vlevo v kontaktu s korenem s1, a l4/5 s cirkularni protruzi. nalez nevysvetluje uplne rozsah a trvani obtizi; neni pritomna komprese korene ani stenoza kanalu, ktere by menily terapeuticky postup. doporucen konzervativni postup a fyzioterapie. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-bezdickova-fyzio-2025a', 'p-bezdickova-1971', '2025-02-11', 'physio_note', 'Záznam z fyzioterapie', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie
Pacient:
Jarmila Bezdíčková
Datum narození:
14.5.1971
Datum terapie:
11.2.2025
Terapeut:
Mgr. Petr Hlaváček
Diagnóza: chronický vertebrogenní algický syndrom bederní páteře, degenerativní změny L4/5 a L5/S1.
Návštěva: 6. ze série 10.
Subjektivně
Od zahájení série udává zlepšení. Ranní ztuhlost kratší, zvládne stát v kuchyni bez přerušení, což před terapií nešlo.
Propagace do levé hýždě jen občas a slabší. Domácí cvičení provádí obden.
Bolest (VAS): 3/10 průměrně za poslední týden, maximum 5/10 po delším sedu.
Objektivně
Schoberova distance 4,5 cm (vstupně 3,5 cm). Lateroflexe symetrická. Lasègueův manévr negativní oboustranně.
Palpačně hypertonus paravertebrálních svalů vlevo v úrovni L4–S1, mírnější než vstupně. Bez čitelného neurologického
deficitu, reflexy symetrické.
Terapie
Měkké techniky a postizometrická relaxace paravertebrálních svalů a musculus quadratus lumborum. Aktivace hlubokého
stabilizačního systému v poloze na zádech a v kleku, 3 série po 10 opakováních. Nácvik nastavení pánve při stoji a při
zvedání břemene.
Plán
Pokračovat v sérii, domácí cvičení denně, nikoli obden. Přidat chůzi 30 minut denně. Kontrola za dva týdny.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie pacient: jarmila bezdickova datum narozeni: 14.5.1971 datum terapie: 11.2.2025 terapeut: mgr. petr hlavacek diagnoza: chronicky vertebrogenni algicky syndrom bederni patere, degenerativni zmeny l4/5 a l5/s1. navsteva: 6. ze serie 10. subjektivne od zahajeni serie udava zlepseni. ranni ztuhlost kratsi, zvladne stat v kuchyni bez preruseni, coz pred terapii neslo. propagace do leve hyzde jen obcas a slabsi. domaci cviceni provadi obden. bolest (vas): 3/10 prumerne za posledni tyden, maximum 5/10 po delsim sedu. objektivne schoberova distance 4,5 cm (vstupne 3,5 cm). lateroflexe symetricka. lasegueuv manevr negativni oboustranne. palpacne hypertonus paravertebralnich svalu vlevo v urovni l4–s1, mirnejsi nez vstupne. bez citelneho neurologickeho deficitu, reflexy symetricke. terapie mekke techniky a postizometricka relaxace paravertebralnich svalu a musculus quadratus lumborum. aktivace hlubokeho stabilizacniho systemu v poloze na zadech a v kleku, 3 serie po 10 opakovanich. nacvik nastaveni panve pri stoji a pri zvedani bremene. plan pokracovat v serii, domaci cviceni denne, nikoli obden. pridat chuzi 30 minut denne. kontrola za dva tydny. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-bezdickova-fyzio-2025b', 'p-bezdickova-1971', '2025-10-14', 'physio_note', 'Záznam z fyzioterapie — nová série', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie — nová série
Pacient:
Jarmila Bezdíčková
Datum narození:
14.5.1971
Datum terapie:
14.10.2025
Terapeut:
Mgr. Petr Hlaváček
Diagnóza: chronický vertebrogenní algický syndrom bederní páteře, degenerativní změny L4/5 a L5/S1.
Návštěva: 2. z nové série 10, po osmiměsíční pauze.
Subjektivně
Udává, že bolesti jsou stejné jako na začátku loňské terapie a že jí předchozí série nakonec nepomohla. Poslední týden po
víkendovém stěhování zhoršení. Přiznává, že domácí cvičení přestala provádět zhruba měsíc po skončení minulé série.
Bolest (VAS): 6/10 po víkendu, 3–4/10 v běžném týdnu.
Objektivně
Schoberova distance 4,5 cm, tedy shodně s únorovým měřením a lépe než vstupně v roce 2024. Lateroflexe symetrická,
Lasègueův manévr negativní. Hypertonus paravertebrálních svalů vlevo výraznější než v únoru. Stereotyp zvedání
břemene z předklonu bez zapojení dolních končetin — návrat k původnímu vzorci.
Objektivní nález tedy zůstává lepší než při vstupním vyšetření, zatímco subjektivní hodnocení je horší. Rozdíl odpovídá
akutnímu zhoršení po zátěži a přerušení autoterapie, nikoli progresi strukturálního nálezu; kontrolní zobrazovací vyšetření
není indikováno.
Terapie
Měkké techniky, mobilizace bederní páteře, postizometrická relaxace. Opakovaná instruktáž hlubokého stabilizačního
systému, korekce stereotypu zvedání.
Plán
Domácí cvičení denně, krátká jednotka 10 minut ráno a večer — kratší a pravidelná je pro udržení efektu podstatnější než
delší a občasná. Vysvětlen rozdíl mezi bolestí a poškozením. Kontrola za týden.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie — nova serie pacient: jarmila bezdickova datum narozeni: 14.5.1971 datum terapie: 14.10.2025 terapeut: mgr. petr hlavacek diagnoza: chronicky vertebrogenni algicky syndrom bederni patere, degenerativni zmeny l4/5 a l5/s1. navsteva: 2. z nove serie 10, po osmimesicni pauze. subjektivne udava, ze bolesti jsou stejne jako na zacatku lonske terapie a ze ji predchozi serie nakonec nepomohla. posledni tyden po vikendovem stehovani zhorseni. priznava, ze domaci cviceni prestala provadet zhruba mesic po skonceni minule serie. bolest (vas): 6/10 po vikendu, 3–4/10 v beznem tydnu. objektivne schoberova distance 4,5 cm, tedy shodne s unorovym merenim a lepe nez vstupne v roce 2024. lateroflexe symetricka, lasegueuv manevr negativni. hypertonus paravertebralnich svalu vlevo vyraznejsi nez v unoru. stereotyp zvedani bremene z predklonu bez zapojeni dolnich koncetin — navrat k puvodnimu vzorci. objektivni nalez tedy zustava lepsi nez pri vstupnim vysetreni, zatimco subjektivni hodnoceni je horsi. rozdil odpovida akutnimu zhorseni po zatezi a preruseni autoterapie, nikoli progresi strukturalniho nalezu; kontrolni zobrazovaci vysetreni neni indikovano. terapie mekke techniky, mobilizace bederni patere, postizometricka relaxace. opakovana instruktaz hlubokeho stabilizacniho systemu, korekce stereotypu zvedani. plan domaci cviceni denne, kratka jednotka 10 minut rano a vecer — kratsi a pravidelna je pro udrzeni efektu podstatnejsi nez delsi a obcasna. vysvetlen rozdil mezi bolesti a poskozenim. kontrola za tyden. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-vondrusak-fyzio-2025', 'p-vondrusak-1985', '2025-06-24', 'physio_note', 'Záznam z fyzioterapie — vstupní vyšetření', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie — vstupní vyšetření
Pacient:
Petr Vondrušák
Datum narození:
3.12.1985
Datum terapie:
24.6.2025
Terapeut:
Bc. Lenka Zemanová
Diagnóza: subakromiální impingement pravého ramene, konzervativní postup.
Návštěva: 1. ze série 6, vstupní kineziologický rozbor.
Subjektivně
Bolest pravého ramene při pohybu nad horizontálu, zejména při práci nad hlavou a při plavání kraulem. Trvá 4 měsíce,
začátek plíživý, bez úrazu. V noci ho budí při ležení na pravém boku.
Bolest (VAS): 4/10 při elevaci nad horizontálu, 1/10 v klidu, 5/10 v noci na boku.
Objektivně
Aktivní abdukce do 160°, bolestivý oblouk mezi 70° a 120°. Pasivní rozsah plný. Hawkinsův test vpravo pozitivní, Neerův
test pozitivní, test supraspinatu mírně bolestivý, síla zachována. Protrakce ramen, oslabení dolních fixátorů lopatky,
scapula alata naznačena vpravo.
Terapie
Měkké techniky na musculus trapezius pars descendens a musculus pectoralis minor. Centrace ramenního kloubu,
aktivace dolních fixátorů lopatky, posilování zevních rotátorů s gumou v neutrální pozici, 3 série po 12 opakováních.
Plán
Šest terapií po týdnu. Domácí cvičení denně, dočasně vyloučit plavání kraulem a práci nad hlavou, nahradit plaváním na
zádech. Při nedostatečném efektu po šesti týdnech zvážit doplnění ultrazvukového vyšetření rotátorové manžety.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie — vstupni vysetreni pacient: petr vondrusak datum narozeni: 3.12.1985 datum terapie: 24.6.2025 terapeut: bc. lenka zemanova diagnoza: subakromialni impingement praveho ramene, konzervativni postup. navsteva: 1. ze serie 6, vstupni kineziologicky rozbor. subjektivne bolest praveho ramene pri pohybu nad horizontalu, zejmena pri praci nad hlavou a pri plavani kraulem. trva 4 mesice, zacatek plizivy, bez urazu. v noci ho budi pri lezeni na pravem boku. bolest (vas): 4/10 pri elevaci nad horizontalu, 1/10 v klidu, 5/10 v noci na boku. objektivne aktivni abdukce do 160°, bolestivy oblouk mezi 70° a 120°. pasivni rozsah plny. hawkinsuv test vpravo pozitivni, neeruv test pozitivni, test supraspinatu mirne bolestivy, sila zachovana. protrakce ramen, oslabeni dolnich fixatoru lopatky, scapula alata naznacena vpravo. terapie mekke techniky na musculus trapezius pars descendens a musculus pectoralis minor. centrace ramenniho kloubu, aktivace dolnich fixatoru lopatky, posilovani zevnich rotatoru s gumou v neutralni pozici, 3 serie po 12 opakovanich. plan sest terapii po tydnu. domaci cviceni denne, docasne vyloucit plavani kraulem a praci nad hlavou, nahradit plavanim na zadech. pri nedostatecnem efektu po sesti tydnech zvazit doplneni ultrazvukoveho vysetreni rotatorove manzety. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-trefilova-rtg-2026', 'p-trefilova-1958', '2026-02-05', 'imaging', 'RTG kolenních kloubů ve stoji — popis', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Radiodiagnostické pracoviště
RTG kolenních kloubů ve stoji — popis
Pacient:
Hana Trefilová
Datum narození:
21.8.1958
Datum vyšetření:
5.2.2026
Popsal:
MUDr. Eva Puchmertlová
Provedené vyšetření
Technika: RTG obou kolenních kloubů předozadně ve stoji se zátěží, bočné snímky vleže.
Indikace: bolesti levého kolena při chůzi a po zátěži, trvající tři roky, postupné zhoršování.
Popis
Vlevo je kloubní štěrbina mediálního kompartmentu zúžená na 1,5 mm, se subchondrální sklerózou a osteofyty na okraji
mediálního kondylu femuru i tibiálního plató. Laterální kompartment se štěrbinou 4 mm. Femoropatelární skloubení s
osteofyty na horním pólu patelly. Osa končetiny mírně varózní.
Vpravo je kloubní štěrbina zachovalá v obou kompartmentech, s naznačenými osteofyty mediálně. Femoropatelární
skloubení bez výraznějších změn.
Kostní struktura odpovídá věku. Bez ložiskových změn, bez známek zánětu, bez volných kloubních tělísek. Měkké tkáně
bez kalcifikací a bez výpotku.
Závěr
Gonartróza vlevo, pokročilá v mediálním kompartmentu (odpovídá stupni III podle Kellgrena a Lawrence), s varózní osou.
Vpravo počínající degenerativní změny. Nález odpovídá klinickým obtížím; v tuto chvíli je namístě konzervativní postup, o
náhradě kloubu rozhodnout podle vývoje obtíží a funkčního omezení.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. radiodiagnosticke pracoviste rtg kolennich kloubu ve stoji — popis pacient: hana trefilova datum narozeni: 21.8.1958 datum vysetreni: 5.2.2026 popsal: mudr. eva puchmertlova provedene vysetreni technika: rtg obou kolennich kloubu predozadne ve stoji se zatezi, bocne snimky vleze. indikace: bolesti leveho kolena pri chuzi a po zatezi, trvajici tri roky, postupne zhorsovani. popis vlevo je kloubni sterbina medialniho kompartmentu zuzena na 1,5 mm, se subchondralni sklerozou a osteofyty na okraji medialniho kondylu femuru i tibialniho plato. lateralni kompartment se sterbinou 4 mm. femoropatelarni skloubeni s osteofyty na hornim polu patelly. osa koncetiny mirne varozni. vpravo je kloubni sterbina zachovala v obou kompartmentech, s naznacenymi osteofyty medialne. femoropatelarni skloubeni bez vyraznejsich zmen. kostni struktura odpovida veku. bez loziskovych zmen, bez znamek zanetu, bez volnych kloubnich telisek. mekke tkane bez kalcifikaci a bez vypotku. zaver gonartroza vlevo, pokrocila v medialnim kompartmentu (odpovida stupni iii podle kellgrena a lawrence), s varozni osou. vpravo pocinajici degenerativni zmeny. nalez odpovida klinickym obtizim; v tuto chvili je namiste konzervativni postup, o nahrade kloubu rozhodnout podle vyvoje obtizi a funkcniho omezeni. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');
INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-skaloud-fyzio-2025', 'p-skaloud-1993', '2025-04-02', 'physio_note', 'Záznam z fyzioterapie', 'Ortopedie a fyzioterapie Podhájí s.r.o.
Pracoviště fyzioterapie
Záznam z fyzioterapie
Pacient:
Radim Škaloud
Datum narození:
8.3.1993
Datum terapie:
2.4.2025
Terapeut:
Mgr. Petr Hlaváček
Diagnóza: stav po distorzi pravého hlezenního kloubu 12. 3. 2025, léze zevního postranního vazu I.–II. stupně.
Návštěva: 3. ze série 5.
Subjektivně
Bolest jen při došlapu na nerovný terén. Chůze bez opory, ortézu nosí při delší chůzi venku. Chce vědět, kdy může začít
znovu běhat.
Bolest (VAS): 2/10 na nerovném terénu, 0/10 v klidu.
Objektivně
Reziduální otok pod zevním kotníkem, obvod přes kotníky vpravo o 0,5 cm větší. Palpační citlivost při úponu předního
talofibulárního vazu. Dorzální flexe 15°, plantární flexe plná. Přední zásuvka hlezna negativní, kloub stabilní. Stoj na jedné
noze 25 sekund se zvýšenou oscilací.
Terapie
Lymfatické techniky, mobilizace hlezna a nohy. Senzomotorický trénink: stoj na labilní ploše, výpady, poskoky na místě.
Posilování peroneálních svalů s odporovou gumou.
Plán
Návrat k běhu na rovném povrchu od příštího týdne, zpočátku střídat běh a chůzi. Terén a změny směru nejdříve za tři
týdny. Ortéza při sportu ještě dva měsíce. Senzomotorické cvičení denně.
Ortopedie a fyzioterapie Podhájí s.r.o.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'ortopedie a fyzioterapie podhaji s.r.o. pracoviste fyzioterapie zaznam z fyzioterapie pacient: radim skaloud datum narozeni: 8.3.1993 datum terapie: 2.4.2025 terapeut: mgr. petr hlavacek diagnoza: stav po distorzi praveho hlezenniho kloubu 12. 3. 2025, leze zevniho postranniho vazu i.–ii. stupne. navsteva: 3. ze serie 5. subjektivne bolest jen pri doslapu na nerovny teren. chuze bez opory, ortezu nosi pri delsi chuzi venku. chce vedet, kdy muze zacit znovu behat. bolest (vas): 2/10 na nerovnem terenu, 0/10 v klidu. objektivne rezidualni otok pod zevnim kotnikem, obvod pres kotniky vpravo o 0,5 cm vetsi. palpacni citlivost pri uponu predniho talofibularniho vazu. dorzalni flexe 15°, plantarni flexe plna. predni zasuvka hlezna negativni, kloub stabilni. stoj na jedne noze 25 sekund se zvysenou oscilaci. terapie lymfaticke techniky, mobilizace hlezna a nohy. senzomotoricky trenink: stoj na labilni plose, vypady, poskoky na miste. posilovani peronealnich svalu s odporovou gumou. plan navrat k behu na rovnem povrchu od pristiho tydne, zpocatku stridat beh a chuzi. teren a zmeny smeru nejdrive za tri tydny. orteza pri sportu jeste dva mesice. senzomotoricke cviceni denne. ortopedie a fyzioterapie podhaji s.r.o. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');

